"""Screen 0 — Welcome & architecture overview."""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib

from .base import BasePage
from ..svg_assets import make_shield_image
from ..state import WizardState
from typing import Callable


def _make_info_row(icon_widget: Gtk.Widget, title: str, subtitle: str) -> Gtk.ListBoxRow:
    """
    Build a plain Gtk.ListBoxRow containing an icon, a bold title label,
    and a dimmed subtitle label.

    Avoids Adw.ActionRow entirely — set_title() on ActionRow is unreliable
    when called after construction in some Libadwaita versions, causing the
    title to render invisible even though it is in the widget tree.
    """
    row = Gtk.ListBoxRow()
    row.set_activatable(False)
    row.set_selectable(False)

    outer = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=12)
    outer.set_margin_top(10)
    outer.set_margin_bottom(10)
    outer.set_margin_start(12)
    outer.set_margin_end(12)

    # Icon
    icon_widget.set_valign(Gtk.Align.CENTER)
    outer.append(icon_widget)

    # Text column
    text_col = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
    text_col.set_valign(Gtk.Align.CENTER)
    text_col.set_hexpand(True)

    title_lbl = Gtk.Label(label=title)
    title_lbl.set_xalign(0)
    title_lbl.set_wrap(True)
    title_lbl.add_css_class("heading")
    text_col.append(title_lbl)

    sub_lbl = Gtk.Label(label=subtitle)
    sub_lbl.set_xalign(0)
    sub_lbl.set_wrap(True)
    sub_lbl.add_css_class("caption")
    sub_lbl.add_css_class("dim-label")
    text_col.append(sub_lbl)

    outer.append(text_col)
    row.set_child(outer)
    return row


def _icon(name: str, size: int = 16) -> Gtk.Image:
    img = Gtk.Image.new_from_icon_name(name)
    img.set_pixel_size(size)
    return img


class WelcomeScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="Welcome", tag="welcome")

    def _build(self):
        # ── Hero ──────────────────────────────────────────────────────────
        hero = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8)
        hero.set_margin_bottom(8)

        shield = make_shield_image(color="#546ac1", pixel_size=64)
        shield.set_margin_bottom(12)
        hero.append(shield)

        title = Gtk.Label(label="Welcome to BulwarkOS")
        title.add_css_class("title-1")
        title.set_justify(Gtk.Justification.CENTER)
        hero.append(title)

        sub = Gtk.Label(
            label="This wizard configures your hardware isolation stack.\n"
                  "First run takes 5–10 minutes and requires a reboot.\n"
                  "Re-running skips steps that are already complete."
        )
        sub.add_css_class("body")
        sub.add_css_class("dim-label")
        sub.set_justify(Gtk.Justification.CENTER)
        sub.set_wrap(True)
        hero.append(sub)
        self._body.append(hero)

        # ── What the wizard does ──────────────────────────────────────────
        steps_group = Adw.PreferencesGroup()
        steps_group.set_title("What this wizard does")

        steps_lb = Gtk.ListBox()
        steps_lb.set_selection_mode(Gtk.SelectionMode.NONE)
        steps_lb.add_css_class("boxed-list")

        steps = [
            (_icon("dialog-information-symbolic"),
             "Detects your hardware",
             "Confirms IOMMU is active and enumerates IOMMU groups."),
            (_icon("network-wired-symbolic"),
             "Configures NIC passthrough",
             "Passes your physical NICs to sys-net via VFIO. "
             "The host never touches the network directly after setup."),
            (_icon("computer-symbolic"),
             "Provisions AppVMs",
             "Creates sys-net, sys-firewall, and your chosen AppVMs "
             "(personal, work, banking, etc.)."),
            (_icon("preferences-system-symbolic"),
             "Writes kernel & VFIO config",
             "Appends IOMMU kernel args, writes modprobe.d config, and "
             "rebuilds the initramfs. Skipped if already done."),
            (_icon("view-refresh-symbolic"),
             "Requires one reboot",
             "VFIO passthrough becomes active after the next boot. "
             "AppVMs can be started immediately after."),
        ]

        for icon_widget, row_title, row_sub in steps:
            steps_lb.append(_make_info_row(icon_widget, row_title, row_sub))

        steps_group.add(steps_lb)
        self._body.append(steps_group)

        # ── Architecture summary ──────────────────────────────────────────
        arch_group = Adw.PreferencesGroup()
        arch_group.set_title("How BulwarkOS isolates your system")

        arch_lb = Gtk.ListBox()
        arch_lb.set_selection_mode(Gtk.SelectionMode.NONE)
        arch_lb.add_css_class("boxed-list")

        # Shield icon white for sys-firewall — matches all other sidebar icons
        arch_items = [
            (_icon("network-wired-symbolic"),
             "sys-net",
             "Physical NICs received via VFIO. "
             "The host has no direct network access after setup."),
            (make_shield_image(color="white", pixel_size=16),
             "sys-firewall",
             "All AppVM traffic routes through this VM. "
             "nftables enforces traffic policy."),
            (_icon("computer-symbolic"),
             "AppVMs",
             "Each trust domain (personal, work, banking, disposable) "
             "runs in its own isolated KVM VM."),
            (_icon("user-trash-symbolic"),
             "Disposable VM",
             "Boots Tails OS from ISO. Amnesic — all session data is "
             "wiped on shutdown. Traffic routed through Tor."),
        ]

        for icon_widget, row_title, row_sub in arch_items:
            arch_lb.append(_make_info_row(icon_widget, row_title, row_sub))

        arch_group.add(arch_lb)
        self._body.append(arch_group)

        # Reboot / re-run notice
        note = Adw.Banner()
        note.set_title(
            "A reboot is required after setup to activate VFIO passthrough. "
            "Steps already completed from a previous run will be skipped automatically."
        )
        note.set_revealed(True)
        self._body.append(note)

        btn_row = self.make_button_row(
            back_label=None,
            back_cb=None,
            next_label="Get Started",
            next_cb=lambda: self.go_to("detect"),
        )
        self._body.append(btn_row)
